/**
 * @fileOverview Section numbering engine.
 *
 * Computes section numbers (1, 1.1, 1.1.1, etc.) from tree position alone.
 * Numbers are NEVER stored in text or generated by the model.
 *
 * The renderer calls this to produce headings like "Chapter 1: Introduction"
 * or "2.3 Empirical Literature Review".
 *
 * @module src/lib/generator/grammar/numbering
 */

import { SectionNode } from './types';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface NumberedSection {
  /** The original section node */
  node: SectionNode;

  /** Computed number string: "1", "1.1", "2.3.1", etc. */
  number: string;

  /** Full display string: "Chapter 1: Introduction" or "2.3 Empirical Literature Review" */
  displayText: string;

  /** Depth in the tree (0-indexed) */
  depth: number;

  /** Children with computed numbers */
  children: NumberedSection[];
}

// ---------------------------------------------------------------------------
// Numbering Logic
// ---------------------------------------------------------------------------

/**
 * Compute section numbers for an entire grammar tree.
 *
 * Level-1 nodes that are container chapters get numbered as "Chapter N".
 * Level-1 non-chapter nodes (e.g. Abstract, References) get no chapter number.
 * Level-2 and level-3 nodes get hierarchical numbers (1.1, 1.1.1).
 *
 * @param sections  The root SectionNode[] from a GrammarDefinition
 * @returns         Numbered tree with computed numbers
 */
export function computeNumbering(sections: SectionNode[]): NumberedSection[] {
  // Sort by order first
  const sorted = [...sections].sort((a, b) => a.order - b.order);

  let chapterCounter = 0;
  const result: NumberedSection[] = [];

  for (const node of sorted) {
    if (isChapterNode(node)) {
      chapterCounter++;
      const numbered = numberNode(node, `${chapterCounter}`, 0, true);
      result.push(numbered);
    } else {
      // Non-chapter top-level nodes (Abstract, TOC, References, Acknowledgement)
      // They get no number prefix
      result.push({
        node,
        number: '',
        displayText: node.displayHeading,
        depth: 0,
        children: [],
      });
    }
  }

  return result;
}

/**
 * Recursively number a node and its children.
 */
function numberNode(
  node: SectionNode,
  parentNumber: string,
  depth: number,
  isChapter: boolean,
): NumberedSection {
  const sortedChildren = [...node.children].sort((a, b) => a.order - b.order);

  const children: NumberedSection[] = sortedChildren.map((child, index) => {
    const childNumber = `${parentNumber}.${index + 1}`;
    return numberNode(child, childNumber, depth + 1, false);
  });

  let displayText: string;
  if (isChapter && depth === 0) {
    displayText = `Chapter ${parentNumber}: ${node.displayHeading}`;
  } else if (parentNumber) {
    displayText = `${parentNumber} ${node.displayHeading}`;
  } else {
    displayText = node.displayHeading;
  }

  return {
    node,
    number: parentNumber,
    displayText,
    depth,
    children,
  };
}

/**
 * Determine if a top-level node should be numbered as a chapter.
 *
 * Chapters are container nodes at level 1 that aren't prelims (abstract,
 * acknowledgement, TOC) or back matter (references).
 */
function isChapterNode(node: SectionNode): boolean {
  const nonChapterRoles = new Set([
    'abstract',
    'acknowledgement',
    'table_of_contents',
    'references',
  ]);
  return node.level === 1 && !nonChapterRoles.has(node.role);
}

// ---------------------------------------------------------------------------
// Flattening Utilities
// ---------------------------------------------------------------------------

/**
 * Flatten the numbered tree into a sequential list (depth-first).
 * Useful for rendering the full document or a table of contents.
 */
export function flattenNumberedSections(numbered: NumberedSection[]): NumberedSection[] {
  const result: NumberedSection[] = [];

  function walk(section: NumberedSection): void {
    result.push(section);
    for (const child of section.children) {
      walk(child);
    }
  }

  for (const section of numbered) {
    walk(section);
  }

  return result;
}

/**
 * Build a lookup map from section node ID → computed number string.
 * Useful for cross-referencing.
 */
export function buildNumberMap(numbered: NumberedSection[]): Map<string, string> {
  const map = new Map<string, string>();

  function walk(section: NumberedSection): void {
    map.set(section.node.id, section.number);
    for (const child of section.children) {
      walk(child);
    }
  }

  for (const section of numbered) {
    walk(section);
  }

  return map;
}

/**
 * Validate that numbering is sequential and correctly hierarchical.
 * Returns an array of error messages (empty = valid).
 */
export function validateNumbering(numbered: NumberedSection[]): string[] {
  const errors: string[] = [];
  const flat = flattenNumberedSections(numbered);

  // Check no duplicate numbers
  const seen = new Set<string>();
  for (const section of flat) {
    if (section.number && seen.has(section.number)) {
      errors.push(`Duplicate section number: "${section.number}" on node "${section.node.id}"`);
    }
    if (section.number) {
      seen.add(section.number);
    }
  }

  // Check parent-child number consistency
  function checkHierarchy(section: NumberedSection): void {
    for (const child of section.children) {
      if (section.number && child.number && !child.number.startsWith(section.number + '.')) {
        errors.push(
          `Child "${child.node.id}" number "${child.number}" does not nest under parent "${section.node.id}" number "${section.number}"`
        );
      }
      checkHierarchy(child);
    }
  }

  for (const section of numbered) {
    checkHierarchy(section);
  }

  return errors;
}
